import{_ as t,o,c as a,ax as n}from"./chunks/framework.Bnt0oLax.js";const p=JSON.parse('{"title":"Changelog","description":"Release history of Developer Studio — new features, changes, and fixes","frontmatter":{"description":"Release history of Developer Studio — new features, changes, and fixes"},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md"}'),r={name:"changelog.md"};function i(s,e,c,d,l,h){return o(),a("div",null,[...e[0]||(e[0]=[n('<div style="display:none;" hidden data-nosnippet>Are you an LLM? You can read better optimized documentation at /docs/changelog.md for this page in Markdown format</div><h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><p>Changes and additions to Developer Studio, ordered by date (newest first).</p><h2 id="_2026-08-27-connectors-templated-hosts-in-urls" tabindex="-1">2026-08-27 - Connectors: Templated Hosts in URLs <a class="header-anchor" href="#_2026-08-27-connectors-templated-hosts-in-urls" aria-label="Permalink to &quot;2026-08-27 - Connectors: Templated Hosts in URLs&quot;">​</a></h2><p>Connector URLs now accept a Variable in the host, not just in the path and query string — either as one label of the host or as the entire base URL. A single connector definition can therefore target a different host per community. The host can also name a fallback with the <code>default()</code> filter, so one connector serves a shared host everywhere and only the communities that need their own have to set the Variable; adding <code>true</code> as the second argument falls back when the Variable exists but is empty. See <a href="/docs/connectors/configuration.html#templating-the-host">Configuration</a> for details.</p><h2 id="_2026-08-05-connectors-longer-response-window-for-external-apis" tabindex="-1">2026-08-05 - Connectors: Longer Response Window for External APIs <a class="header-anchor" href="#_2026-08-05-connectors-longer-response-window-for-external-apis" aria-label="Permalink to &quot;2026-08-05 - Connectors: Longer Response Window for External APIs&quot;">​</a></h2><p>Connectors now allow an external API up to 15 seconds to respond, so integrations with slower endpoints complete successfully instead of returning a proxy error. The same window applies to each step of a composite connector and to the token request for OAuth-authenticated connectors. See <a href="/docs/connectors/how-connectors-work.html">How Connectors Work</a> for details.</p><h2 id="_2026-07-29-connectors-variables-for-reusable-configuration" tabindex="-1">2026-07-29 - Connectors: Variables for Reusable Configuration <a class="header-anchor" href="#_2026-07-29-connectors-variables-for-reusable-configuration" aria-label="Permalink to &quot;2026-07-29 - Connectors: Variables for Reusable Configuration&quot;">​</a></h2><p>Connectors now support <strong>Variables</strong> — named, plain-text configuration values such as base URLs, environment IDs, and instance identifiers that you store once and reference across connectors with <code>get_variable(&#39;name&#39;)</code>. Unlike secrets, a Variable can be used directly in a connector&#39;s URL, so you can point the same connector at a sandbox or production host without editing it. See <a href="/docs/connectors/secrets/">Secrets and Variables</a> for details.</p><h2 id="_2026-07-14-widget-manifests-unknown-or-misplaced-attributes-are-rejected" tabindex="-1">2026-07-14 - Widget Manifests: Unknown or Misplaced Attributes Are Rejected <a class="header-anchor" href="#_2026-07-14-widget-manifests-unknown-or-misplaced-attributes-are-rejected" aria-label="Permalink to &quot;2026-07-14 - Widget Manifests: Unknown or Misplaced Attributes Are Rejected&quot;">​</a></h2><p>Your widget source manifest (<code>extensions_registry.json</code>) now reports a clear error identifying the offending attribute path when it contains an unknown or misplaced key — a misspelled or wrongly-nested attribute — when you sync it from your repository or preview a widget, instead of silently dropping it and reporting success. See <a href="/docs/custom-widgets/v2/registry-reference.html">Registry Reference</a> for details.</p><h2 id="_2026-06-24-connectors-duplicate-parameter-keys-are-rejected" tabindex="-1">2026-06-24 - Connectors: Duplicate Parameter Keys Are Rejected <a class="header-anchor" href="#_2026-06-24-connectors-duplicate-parameter-keys-are-rejected" aria-label="Permalink to &quot;2026-06-24 - Connectors: Duplicate Parameter Keys Are Rejected&quot;">​</a></h2><p>Connector definitions now require each header, query parameter, and path parameter key to be unique. Duplicate keys are reported as a clear configuration error when you save a connector, sync it from a repository, or run a connection test — instead of silently keeping only the last value. See <a href="/docs/connectors/headers-and-query-parameters.html">Headers &amp; Query Parameters</a> for details.</p><h2 id="_2026-06-17-connectors-api-key-is-now-the-canonical-authentication-type" tabindex="-1">2026-06-17 - Connectors: <code>api_key</code> Is Now the Canonical Authentication Type <a class="header-anchor" href="#_2026-06-17-connectors-api-key-is-now-the-canonical-authentication-type" aria-label="Permalink to &quot;2026-06-17 - Connectors: `api_key` Is Now the Canonical Authentication Type&quot;">​</a></h2><p>API key authentication now uses <code>api_key</code> as its canonical type identifier (matching the <code>oauth_client_credentials</code> / <code>oauth_jwt_bearer</code> naming convention). The previous spelling <code>apikey</code> is <strong>soft-deprecated</strong> — it is permanently retained as a backward-compatible alias and is never rejected. Both spellings are accepted at all write boundaries and execute identically. Existing connectors previously stored with <code>&quot;apikey&quot;</code> are transparently migrated to <code>api_key</code>; no manual changes are required. See <a href="/docs/connectors/authentication.html">Authentication</a> for details.</p><h2 id="_2026-06-15-connector-sync-from-repositories-is-now-all-or-nothing" tabindex="-1">2026-06-15 - Connector Sync from Repositories Is Now All-or-Nothing <a class="header-anchor" href="#_2026-06-15-connector-sync-from-repositories-is-now-all-or-nothing" aria-label="Permalink to &quot;2026-06-15 - Connector Sync from Repositories Is Now All-or-Nothing&quot;">​</a></h2><p>Connector sync from a repository&#39;s <code>connectors_registry.json</code> is now all-or-nothing: if any connector or composite connector has an invalid field, the entire sync is rejected with a clear error naming the connector and every field to fix, and no changes are applied. A repository&#39;s connectors always sync as a consistent set, rather than some going live while others are silently left out. See <a href="/docs/connectors/repository-registry.html">Repository Registry</a> for details.</p><h2 id="_2026-06-15-clearer-connector-build-errors-and-documented-field-limits" tabindex="-1">2026-06-15 - Clearer Connector Build Errors and Documented Field Limits <a class="header-anchor" href="#_2026-06-15-clearer-connector-build-errors-and-documented-field-limits" aria-label="Permalink to &quot;2026-06-15 - Clearer Connector Build Errors and Documented Field Limits&quot;">​</a></h2><p>When a connector in <code>connectors_registry.json</code> has an invalid or over-length field, the build error now names the connector and the field to fix instead of showing internal details. Connector field limits — URL, name, header and query values, response content type, and permalink — are now documented. See <a href="/docs/connectors/repository-registry.html">Repository Registry</a> for details.</p><h2 id="_2026-06-12-connector-urls-support-up-to-2048-characters" tabindex="-1">2026-06-12 - Connector URLs Support Up to 2048 Characters <a class="header-anchor" href="#_2026-06-12-connector-urls-support-up-to-2048-characters" aria-label="Permalink to &quot;2026-06-12 - Connector URLs Support Up to 2048 Characters&quot;">​</a></h2><p>Connector URLs now support up to 2048 characters, accommodating templates with multiple path and query parameter placeholders. Repositories whose connector sync was failing due to URL length will succeed on the next push. See <a href="/docs/connectors/dynamic-url-paths.html">Dynamic URL Path Segments</a> for details on URL templates.</p><h2 id="_2026-05-27-dynamic-url-path-segments-in-connectors" tabindex="-1">2026-05-27 - Dynamic URL Path Segments in Connectors <a class="header-anchor" href="#_2026-05-27-dynamic-url-path-segments-in-connectors" aria-label="Permalink to &quot;2026-05-27 - Dynamic URL Path Segments in Connectors&quot;">​</a></h2><p>Connectors can now use caller-supplied values as path segments in the upstream URL — for example, fetching <code>https://api.example.com/ideas/42/endorsements</code> where <code>42</code> is supplied by the widget per call. Declare each variable segment as a <strong>path parameter</strong> and reference it from the URL with <code>{{ pathParams.X }}</code>. Values are validated as URL-safe (letters, digits, and <code>. _ ~ -</code>; max 200 chars; no path-traversal segments) before any outbound call is made, and the upstream host stays locked to the connector&#39;s configured prefix. Callers pass the values via the new <code>pathParams</code> field on the SDK&#39;s <code>execute</code> method. See <a href="/docs/connectors/dynamic-url-paths.html">Dynamic URL Path Segments</a> for details.</p><h2 id="_2026-05-14-composite-connectors" tabindex="-1">2026-05-14 - Composite Connectors <a class="header-anchor" href="#_2026-05-14-composite-connectors" aria-label="Permalink to &quot;2026-05-14 - Composite Connectors&quot;">​</a></h2><p>Chain multiple API calls into a single execution. Define an ordered sequence of steps in <code>connectors_registry.json</code> — each step calls an external API, and its response feeds into the next step via Jinja2 templates. The final step&#39;s response is returned to the widget. Supports per-step authentication, response transformation, and access to the client&#39;s incoming request data. See <a href="/docs/connectors/composite-connectors.html">Build a Composite Connector</a> for details.</p><h2 id="_2026-04-29-scripts-and-stylesheets-attributes-field-now-honored" tabindex="-1">2026-04-29 - Scripts and Stylesheets: <code>attributes</code> Field Now Honored <a class="header-anchor" href="#_2026-04-29-scripts-and-stylesheets-attributes-field-now-honored" aria-label="Permalink to &quot;2026-04-29 - Scripts and Stylesheets: `attributes` Field Now Honored&quot;">​</a></h2><p>The <code>attributes</code> object on script and stylesheet entries in <code>extensions_registry.json</code> was being silently dropped during validation. It is now preserved end-to-end and appears in the widget registry response. Repositories already declaring <code>attributes</code> will see them take effect on the next registry refresh.</p><h2 id="_2026-04-22-build-status-non-fatal-advisory-warnings" tabindex="-1">2026-04-22 - Build Status: Non-Fatal Advisory Warnings <a class="header-anchor" href="#_2026-04-22-build-status-non-fatal-advisory-warnings" aria-label="Permalink to &quot;2026-04-22 - Build Status: Non-Fatal Advisory Warnings&quot;">​</a></h2><p>The build status on GitHub repository sources now includes a <code>warnings</code> array alongside <code>state</code> and <code>error</code>, surfacing non-fatal advisories detected on the latest build. The first advisory reports when a repository still uses the deprecated <code>widget_registry.json</code> filename, so you can spot the rename opportunity before the legacy fallback is removed.</p><h2 id="_2026-04-22-widget-registry-settings-shared-default-is-now-false" tabindex="-1">2026-04-22 - Widget Registry: <code>settings.shared</code> Default Is Now <code>false</code> <a class="header-anchor" href="#_2026-04-22-widget-registry-settings-shared-default-is-now-false" aria-label="Permalink to &quot;2026-04-22 - Widget Registry: `settings.shared` Default Is Now `false`&quot;">​</a></h2><p>When a widget in <code>extensions_registry.json</code> omits <code>settings.shared</code>, it now defaults to <code>false</code> (previously <code>true</code>). Authors who want cross-page sharing must set <code>settings.shared</code> to <code>true</code> explicitly. See <a href="/docs/custom-widgets/v2/widget-schema.html#settings-object">Widget Definition Reference</a> for the full settings reference.</p><h2 id="_2026-04-22-widget-registry-non-array-configuration-properties-rejected-with-targeted-error" tabindex="-1">2026-04-22 - Widget Registry: Non-Array <code>configuration.properties</code> Rejected with Targeted Error <a class="header-anchor" href="#_2026-04-22-widget-registry-non-array-configuration-properties-rejected-with-targeted-error" aria-label="Permalink to &quot;2026-04-22 - Widget Registry: Non-Array `configuration.properties` Rejected with Targeted Error&quot;">​</a></h2><p>In <code>extensions_registry.json</code>, <code>configuration.properties</code> must be an array of field definitions. Builds with the common JSON-Schema-style object shape are now rejected with a targeted error showing the correct shape. See <a href="/docs/custom-widgets/v2/widget-schema.html#configuration-object">Widget Definition Reference</a> for details.</p><h2 id="_2026-04-22-widget-registry-category-is-now-required" tabindex="-1">2026-04-22 - Widget Registry: <code>category</code> Is Now Required <a class="header-anchor" href="#_2026-04-22-widget-registry-category-is-now-required" aria-label="Permalink to &quot;2026-04-22 - Widget Registry: `category` Is Now Required&quot;">​</a></h2><p>Every widget in <code>extensions_registry.json</code> must declare a <code>category</code>. Publishes without one are rejected with a clear error identifying the missing field. Existing widgets that already declare a category are unaffected. See <a href="/docs/custom-widgets/v2/widget-schema.html">Widget Definition Reference</a> for the full widget schema.</p><h2 id="_2026-04-21-extensions-registry-canonical-filename-renamed-to-extensions-registry-json" tabindex="-1">2026-04-21 - Extensions Registry: Canonical Filename Renamed to <code>extensions_registry.json</code> <a class="header-anchor" href="#_2026-04-21-extensions-registry-canonical-filename-renamed-to-extensions-registry-json" aria-label="Permalink to &quot;2026-04-21 - Extensions Registry: Canonical Filename Renamed to `extensions_registry.json`&quot;">​</a></h2><p>The registry file at the root of your repository is now named <code>extensions_registry.json</code>. The old filename <code>widget_registry.json</code> is deprecated and still works during a migration window, but will be removed in a future release — rename it at your earliest convenience. No schema changes are required; the file contents remain identical. See <a href="/docs/custom-widgets/v2/project-setup.html">Repository Layout</a> for details.</p><h2 id="_2026-04-20-html-attributes-for-scripts-and-stylesheets" tabindex="-1">2026-04-20 - HTML Attributes for Scripts and Stylesheets <a class="header-anchor" href="#_2026-04-20-html-attributes-for-scripts-and-stylesheets" aria-label="Permalink to &quot;2026-04-20 - HTML Attributes for Scripts and Stylesheets&quot;">​</a></h2><p>Custom scripts and stylesheets now support an optional <code>attributes</code> field for standard HTML attributes like <code>defer</code>, <code>async</code>, and <code>crossorigin</code>, giving widget creators control over loading behavior and execution timing. See <a href="/docs/custom-widgets/v2/scripts.html#html-attributes">Script Definition Reference</a> and <a href="/docs/custom-widgets/v2/stylesheets.html#html-attributes">Stylesheet Definition Reference</a> for details.</p><h2 id="_2026-04-16-removed-legacy-template-customization-for-widgets" tabindex="-1">2026-04-16 - Removed Legacy Template Customization for Widgets <a class="header-anchor" href="#_2026-04-16-removed-legacy-template-customization-for-widgets" aria-label="Permalink to &quot;2026-04-16 - Removed Legacy Template Customization for Widgets&quot;">​</a></h2><p>Widget HTML is no longer processed as a Jinja2 template at render time. Previously, query parameters on the render URL were injected into <code>{{ }}</code> placeholders in widget HTML — this legacy mechanism has been removed. Widgets that used this pattern should migrate to <a href="/docs/custom-widgets/v2/configurable-widgets.html"><code>sdk.getProps()</code></a> for all runtime configuration needs.</p><h2 id="_2026-03-30-response-transformation-for-connectors" tabindex="-1">2026-03-30 - Response Transformation for Connectors <a class="header-anchor" href="#_2026-03-30-response-transformation-for-connectors" aria-label="Permalink to &quot;2026-03-30 - Response Transformation for Connectors&quot;">​</a></h2><p>Connectors can now reshape upstream API responses before returning them to the widget. Configure a Jinja2 template to extract specific fields, reformat JSON, or normalize error responses — all on the server, without any client-side logic. An optional content-type override lets you change the response format when the template produces a different output type. See <a href="/docs/connectors/response-transformation.html">Response Transformation</a> for details.</p><h2 id="_2026-02-25-repository-based-connector-definitions" tabindex="-1">2026-02-25 - Repository-Based Connector Definitions <a class="header-anchor" href="#_2026-02-25-repository-based-connector-definitions" aria-label="Permalink to &quot;2026-02-25 - Repository-Based Connector Definitions&quot;">​</a></h2><p>Connectors can now be defined alongside widgets in a <code>connectors_registry.json</code> file at the repository root, validated and synced automatically on every push — ensuring the repository remains the single source of truth. See <a href="/docs/connectors/repository-registry.html">Repository Registry</a> for details.</p><h2 id="_2026-02-19-manage-github-accounts-and-disconnect" tabindex="-1">2026-02-19 - Manage GitHub Accounts and Disconnect <a class="header-anchor" href="#_2026-02-19-manage-github-accounts-and-disconnect" aria-label="Permalink to &quot;2026-02-19 - Manage GitHub Accounts and Disconnect&quot;">​</a></h2><p>You can now manage GitHub account connections from one place: connect additional accounts, disconnect an account from your community without uninstalling the app from GitHub, and reconnect later if needed. See <a href="/docs/custom-widgets/v2/connect-github.html">Connect Your GitHub Account</a> for details.</p><h2 id="_2026-02-19-credential-scanning" tabindex="-1">2026-02-19 - Credential Scanning <a class="header-anchor" href="#_2026-02-19-credential-scanning" aria-label="Permalink to &quot;2026-02-19 - Credential Scanning&quot;">​</a></h2><p>Widget code is now scanned for hardcoded credentials — including API keys, private keys, and access tokens — before publishing, with flagged builds blocked to prevent accidental secret exposure. See <a href="/docs/custom-widgets/v2/content-security.html">Content Security</a> for details.</p><h2 id="_2026-02-12-widget-thumbnails-via-relative-imagesrc" tabindex="-1">2026-02-12 - Widget Thumbnails via Relative imageSrc <a class="header-anchor" href="#_2026-02-12-widget-thumbnails-via-relative-imagesrc" aria-label="Permalink to &quot;2026-02-12 - Widget Thumbnails via Relative imageSrc&quot;">​</a></h2><p>Widget creators can now use relative paths in imageSrc for widget preview images, keeping thumbnails in the same repository as the widget instead of hosting them externally.</p><h2 id="_2026-02-12-content-safety-scanning" tabindex="-1">2026-02-12 - Content Safety Scanning <a class="header-anchor" href="#_2026-02-12-content-safety-scanning" aria-label="Permalink to &quot;2026-02-12 - Content Safety Scanning&quot;">​</a></h2><p>Widget code is now automatically scanned for security issues — including crypto mining, data exfiltration, phishing, and obfuscated code — before publishing, with flagged builds rejected alongside a clear error message. See <a href="/docs/custom-widgets/v2/content-security.html">Content Security</a> for details.</p><h2 id="_2026-02-11-security-headers-and-cache-invalidation" tabindex="-1">2026-02-11 - Security Headers and Cache Invalidation <a class="header-anchor" href="#_2026-02-11-security-headers-and-cache-invalidation" aria-label="Permalink to &quot;2026-02-11 - Security Headers and Cache Invalidation&quot;">​</a></h2><p>Widget responses now include Referrer-Policy and Permissions-Policy headers, strengthening browser-level protections for embedded widgets. Additionally, deleting a widget now automatically removes cached content, ensuring stale content is no longer served after removal.</p><h2 id="_2026-02-10-delimiter-separated-values-in-connector-configuration" tabindex="-1">2026-02-10 - Delimiter-Separated Values in Connector Configuration <a class="header-anchor" href="#_2026-02-10-delimiter-separated-values-in-connector-configuration" aria-label="Permalink to &quot;2026-02-10 - Delimiter-Separated Values in Connector Configuration&quot;">​</a></h2><p>Connector configuration now accepts delimiter-separated values (comma, pipe, semicolon) in query parameters and headers, such as field selection lists commonly used when calling external APIs.</p><h2 id="_2026-02-04-widget-asset-co-location" tabindex="-1">2026-02-04 - Widget Asset Co-location <a class="header-anchor" href="#_2026-02-04-widget-asset-co-location" aria-label="Permalink to &quot;2026-02-04 - Widget Asset Co-location&quot;">​</a></h2><p>Widget creators can now store assets (CSS, JS, images) alongside widget code and reference them using standard HTML relative paths, simplifying development and improving load performance.</p><h2 id="_2026-02-04-secure-secret-references-in-connector-configuration" tabindex="-1">2026-02-04 - Secure Secret References in Connector Configuration <a class="header-anchor" href="#_2026-02-04-secure-secret-references-in-connector-configuration" aria-label="Permalink to &quot;2026-02-04 - Secure Secret References in Connector Configuration&quot;">​</a></h2><p>Connector configuration now enforces secret references for credential fields, ensuring sensitive values are always stored securely.</p>',61)])])}const g=t(r,[["render",i]]);export{p as __pageData,g as default};
